-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;

-- union<list<int32>, string>: complex branches follow the inferred schema (per-branch type hints
-- align the branch types with Variant alternatives such as Array(Nullable(Int32))), and a non-null
-- union row that selects a null list or string payload becomes a Variant NULL, not the branch's
-- default value. Rows: [1,2], NULL (null list payload), 'a', [3], NULL (null string payload).
DESC format(ORC, unhex(''));
SELECT u, toTypeName(u) FROM format(ORC, unhex('')) ORDER BY toString(u);

-- union<map<string,int32>, int32> with a null map payload. Rows: {'k':1}, NULL, 7.
DESC format(ORC, unhex(''));
SELECT u FROM format(ORC, unhex('')) ORDER BY toString(u);

-- union<struct<a:int32>, string> with a null struct payload. Rows: (1), NULL, 's'.
DESC format(ORC, unhex(''));
SELECT u FROM format(ORC, unhex('')) ORDER BY toString(u);

-- union<int32, string> whose string branch is dictionary-encoded must be readable under the
-- default input_format_orc_dictionary_as_low_cardinality = 1, mapping the branch to
-- LowCardinality(String). Rows: 'apple', 10, 'banana', 'apple', 20, 'apple'.
DESC format(ORC, unhex(''));
SELECT u, toTypeName(u) FROM format(ORC, unhex('')) ORDER BY toString(u) SETTINGS input_format_orc_dictionary_as_low_cardinality = 1;
SELECT u, toTypeName(u) FROM format(ORC, unhex('')) ORDER BY toString(u) SETTINGS input_format_orc_dictionary_as_low_cardinality = 0;

-- An explicit schema propagates per-branch type hints when the correspondence between ORC branches
-- and Variant alternatives is unambiguous: the binary branch is decoded as IPv6 (or Int128), the
-- string branch as String. Rows: ::1, 'text', 2001:db8::1.
SELECT u FROM format(ORC, 'u Variant(IPv6, String)', unhex('')) ORDER BY toString(u);
SELECT u FROM format(ORC, 'u Variant(Int128, String)', unhex('')) ORDER BY toString(u);
